    <?php $maximum = max(1, ...array_map('array_sum', $statisticsData['by_sector'] ?: [[]])); ?><section class="statistics-section"><h3>Graphique par secteur</h3><div class="statistics-chart" role="img" aria-label="Répartition des propositions par statut et par secteur"><?php foreach ($statisticsData['by_sector'] as $sector => $counts): ?><div class="statistics-chart-row"><strong><?= htmlspecialchars((string) $sector) ?></strong><div class="statistics-chart-bar"><?php foreach (array_keys($statisticsData['statuses']) as $status): $count = (int) ($counts[$status] ?? 0); if ($count === 0) continue; ?><span class="statistics-segment statistics-segment--<?= htmlspecialchars($status) ?>" style="width: <?= ($count / $maximum) * 100 ?>%" title="<?= htmlspecialchars((string) $statisticsData['statuses'][$status]) ?> : <?= $count ?>"><?= $count ?></span><?php endforeach; ?></div></div><?php endforeach; ?></div><p class="statistics-legend"><?php foreach ($statisticsData['statuses'] as $status => $label): ?><span><i class="statistics-segment statistics-segment--<?= htmlspecialchars((string) $status) ?>"></i><?= htmlspecialchars((string) $label) ?></span><?php endforeach; ?></p></section>
