me="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="contributeur"><button>Rétrograder</button></form><form method="post" action="<?= htmlspecialchars($routeUrl('/admin/utilisateurs/role'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="super_administrateur"><button>Passer super-admin</button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table>
